  1188→    } else {
  1189→      // === 새 기록 미달성 시: 중앙에 배치 ===
  1190→      // 게임 오버 타이틀
  1191→      this.add.text(200, 180, 'GAME OVER', {
  1192→        fontSize: '48px',
  1193→        color: '#ff0000',
  1194→        fontStyle: 'bold',
  1195→        stroke: '#000000',
  1196→        strokeThickness: 6
  1197→      }).setOrigin(0.5).setDepth(200);
  1198→
  1199→      // 최종 점수
  1200→      this.add.text(200, 260, `점수: ${this.score}`, {
  1201→        fontSize: '32px',
  1202→        color: '#ffffff',
  1203→        fontStyle: 'bold',
  1204→        stroke: '#000000',
  1205→        strokeThickness: 4
  1206→      }).setOrigin(0.5).setDepth(200);
  1207→
  1208→      // 로컬 최고 점수
  1209→      this.add.text(200, 320, `개인 최고: ${this.highScore}`, {
  1210→        fontSize: '24px',
  1211→        color: '#FFD700',
  1212→        stroke: '#000000',
  1213→        strokeThickness: 3
  1214→      }).setOrigin(0.5).setDepth(200);
  1215→
  1216→      // 재시작 안내
  1217→      this.showRestartButton();
  1218→    }
  1219→  }
  1220→
  1221→  /**
  1222→   * 이니셜 입력 UI 표시
  1223→   */
  1224→  private showInitialInputUI() {
  1225→    // 안내 텍스트
  1226→    this.add.text(200, 250, '이니셜 입력 (영어 대문자 3자)', {
  1227→      fontSize: '18px',
  1228→      color: '#ffffff',
  1229→      fontStyle: 'bold',
  1230→      stroke: '#000000',
  1231→      strokeThickness: 3
  1232→    }).setOrigin(0.5).setDepth(200);
  1233→
  1234→    // HTML input 엘리먼트 생성
  1235→    const inputElement = document.createElement('input');
  1236→    inputElement.type = 'text';
  1237→    inputElement.maxLength = 3;
  1238→    inputElement.placeholder = 'ABC';
  1239→    inputElement.style.cssText = `
  1240→      position: absolute;
  1241→      left: 50%;
  1242→      top: 315px;
  1243→      transform: translateX(-50%);
  1244→      width: 120px;
  1245→      height: 40px;
  1246→      font-size: 24px;
  1247→      text-align: center;
  1248→      text-transform: uppercase;
  1249→      border: 3px solid #FFD700;
  1250→      border-radius: 8px;
  1251→      background: #000;
  1252→      color: #fff;
  1253→      font-weight: bold;
  1254→      letter-spacing: 8px;
  1255→    `;
  1256→
  1257→    // 기존 이니셜이 있으면 미리 채우기
  1258→    const existingInitials = getUserInitials();
  1259→    if (existingInitials) {
  1260→      inputElement.value = existingInitials;
  1261→    }
  1262→
  1263→    document.body.appendChild(inputElement);
  1264→    inputElement.focus();
  1265→
  1266→    // 대문자만 입력되도록
  1267→    inputElement.addEventListener('input', (e) => {
  1268→      const target = e.target as HTMLInputElement;
  1269→      target.value = target.value.toUpperCase().replace(/[^A-Z]/g, '');
  1270→    });
  1271→
  1272→    // 제출 버튼 텍스트
  1273→    const submitButtonText = this.add.text(200, 360, '랭킹 등록', {
  1274→      fontSize: '24px',
  1275→      color: '#00ff00',
  1276→      fontStyle: 'bold',
  1277→      stroke: '#000',
  1278→      strokeThickness: 4,
  1279→      padding: { x: 20, y: 10 }
  1280→    }).setOrigin(0.5).setInteractive().setDepth(200);
  1281→
  1282→    // 에러 메시지 영역
  1283→    let errorText: Phaser.GameObjects.Text | null = null;
  1284→
  1285→    // 제출 버튼 클릭
  1286→    submitButtonText.on('pointerdown', async () => {
  1287→      const initials = inputElement.value.trim().toUpperCase();
  1288→
  1289→      // 검증
  1290→      if (initials.length !== 3) {
  1291→        if (errorText) errorText.destroy();
  1292→        errorText = this.add.text(200, 410, '정확히 3글자를 입력하세요', {
  1293→          fontSize: '16px',
  1294→          color: '#ff0000',
  1295→          fontStyle: 'bold',
  1296→          stroke: '#000',
  1297→          strokeThickness: 3
  1298→        }).setOrigin(0.5).setDepth(200);
  1299→        return;
  1300→      }
  1301→
  1302→      if (!/^[A-Z]{3}$/.test(initials)) {
  1303→        if (errorText) errorText.destroy();
  1304→        errorText = this.add.text(200, 410, '영어 대문자만 입력하세요', {
  1305→          fontSize: '16px',
  1306→          color: '#ff0000',
  1307→          fontStyle: 'bold',
  1308→          stroke: '#000',
  1309→          strokeThickness: 3
  1310→        }).setOrigin(0.5).setDepth(200);
  1311→        return;
  1312→      }
  1313→
  1314→      // 이니셜 저장
  1315→      setUserInitials(initials);
  1316→
  1317→      // input 제거
  1318→      document.body.removeChild(inputElement);
  1319→      submitButtonText.destroy();
  1320→      if (errorText) errorText.destroy();
  1321→
  1322→      // 랭킹 제출
  1323→      const submittingText = this.add.text(200, 300, '랭킹 제출 중...', {
  1324→        fontSize: '18px',
  1325→        color: '#ffff00',
  1326→        fontStyle: 'bold',
  1327→        stroke: '#000',
  1328→        strokeThickness: 3
  1329→      }).setOrigin(0.5).setDepth(200);
  1330→
  1331→      try {
  1332→        // 점수 제출 (검증 없이)
  1333→        const result = await submitScore(
  1334→          this.score,
  1335→          this.difficulty,
  1336→          initials
  1337→        );
  1338→
  1339→        submittingText.destroy();
  1340→
  1341→        // 순위 표시
  1342→        if (result.rank !== null) {
  1343→          this.add.text(200, 340, `🏆 전체 ${result.rank}위! 🏆`, {
  1344→            fontSize: '24px',
  1345→            color: '#FFD700',
  1346→            fontStyle: 'bold',
  1347→            stroke: '#000',
  1348→            strokeThickness: 3
  1349→          }).setOrigin(0.5).setDepth(200);
  1350→        }
  1351→
  1352→        // 이니셜 표시
  1353→        this.add.text(200, 380, `${initials}`, {
  1354→          fontSize: '20px',
  1355→          color: '#00ff00',
  1356→          fontStyle: 'bold',
  1357→          stroke: '#000',
  1358→          strokeThickness: 3,
  1359→          letterSpacing: 4
  1360→        }).setOrigin(0.5).setDepth(200);
  1361→
  1362→      } catch (error) {
  1363→        console.error('Failed to submit score:', error);
  1364→        submittingText.setText('❌ 랭킹 제출 실패');
  1365→        submittingText.setColor('#ff0000');
  1366→      }
  1367→
  1368→      // 재시작 버튼 표시
  1369→      this.showRestartButton();
  1370→    });
  1371→
  1372→    // Enter 키로도 제출 가능
  1373→    inputElement.addEventListener('keypress', (e) => {
  1374→      if (e.key === 'Enter') {
  1375→        submitButtonText.emit('pointerdown');
  1376→      }
  1377→    });
  1378→  }
  1379→
  1380→  /**
  1381→   * 재시작 버튼 표시 (다시 하기 + 메인 메뉴) - 버튼 스타일
  1382→   */
  1383→  private showRestartButton() {
  1384→    // 다시 하기 버튼 배경
  1385→    const retryButtonBg = this.add.rectangle(200, 450, 250, 70, 0x00aa00)
  1386→      .setOrigin(0.5)
  1387→      .setDepth(199)
  1388→      .setStrokeStyle(3, 0xffffff);
  1389→
  1390→    // 다시 하기 버튼 텍스트
  1391→    const retryButtonText = this.add.text(200, 450, '다시 하기', {
  1392→      fontSize: '22px',
  1393→      color: '#ffffff',
  1394→      fontStyle: 'bold'
  1395→    }).setOrigin(0.5).setDepth(200);
  1396→
  1397→    // 다시 하기 버튼 인터랙티브 영역 (배경을 클릭 가능하게)
  1398→    retryButtonBg.setInteractive({ useHandCursor: true });
  1399→
  1400→    // 메인 메뉴 버튼 배경
  1401→    const menuButtonBg = this.add.rectangle(200, 555, 250, 70, 0x555555)
  1402→      .setOrigin(0.5)
  1403→      .setDepth(199)
  1404→      .setStrokeStyle(3, 0xffffff);
  1405→
  1406→    // 메인 메뉴 버튼 텍스트
  1407→    const menuButtonText = this.add.text(200, 555, '메인 메뉴', {
  1408→      fontSize: '22px',
  1409→      color: '#ffffff',
  1410→      fontStyle: 'bold'
  1411→    }).setOrigin(0.5).setDepth(200);
  1412→
  1413→    // 메인 메뉴 버튼 인터랙티브 영역
  1414→    menuButtonBg.setInteractive({ useHandCursor: true });
  1415→
  1416→    // 호버 효과 - 다시 하기 버튼
  1417→    retryButtonBg.on('pointerover', () => {
  1418→      retryButtonBg.setFillStyle(0x00ff00);
  1419→      retryButtonBg.setScale(1.05);
  1420→      retryButtonText.setScale(1.05);
  1421→    });
  1422→    retryButtonBg.on('pointerout', () => {
  1423→      retryButtonBg.setFillStyle(0x00aa00);
  1424→      retryButtonBg.setScale(1);
  1425→      retryButtonText.setScale(1);
  1426→    });
  1427→
  1428→    // 호버 효과 - 메인 메뉴 버튼
  1429→    menuButtonBg.on('pointerover', () => {
  1430→      menuButtonBg.setFillStyle(0x777777);
  1431→      menuButtonBg.setScale(1.05);
  1432→      menuButtonText.setScale(1.05);
  1433→    });
  1434→    menuButtonBg.on('pointerout', () => {
  1435→      menuButtonBg.setFillStyle(0x555555);
  1436→      menuButtonBg.setScale(1);
  1437→      menuButtonText.setScale(1);
  1438→    });
  1439→
  1440→    // 0.5초 지연 후 클릭 이벤트 활성화 (의도치 않은 즉시 클릭 방지)
  1441→    this.time.delayedCall(500, () => {
  1442→      // 다시 하기 버튼 클릭
  1443→      retryButtonBg.on('pointerdown', () => {
  1444→        // HTML input이 남아있으면 제거
  1445→        const existingInput = document.querySelector('input');
  1446→        if (existingInput) {
  1447→          document.body.removeChild(existingInput);
  1448→        }
  1449→
  1450→        // 모든 사운드 정리
  1451→        this.sound.stopAll();
  1452→        // 플레이어 효과 정리
  1453→        if (this.player) {
  1454→          this.player.cleanupEffects();
  1455→        }
  1456→
  1457→        // 같은 게임 모드와 난이도로 재시작
  1458→        this.scene.restart({ gameMode: this.gameMode, difficulty: this.difficulty });
  1459→      });
  1460→
  1461→      // 메인 메뉴 버튼 클릭
  1462→      menuButtonBg.on('pointerdown', () => {
  1463→        // HTML input이 남아있으면 제거
  1464→        const existingInput = document.querySelector('input');
  1465→        if (existingInput) {
  1466→          document.body.removeChild(existingInput);
  1467→        }
  1468→
  1469→        // 모든 사운드 정리
  1470→        this.sound.stopAll();
  1471→        // 플레이어 효과 정리
  1472→        if (this.player) {
  1473→          this.player.cleanupEffects();
  1474→        }
  1475→
  1476→        // 모드 선택 씬으로 돌아가기
  1477→        this.scene.start('ModeSelectScene');
  1478→      });
  1479→    });
  1480→  }
  1481→}
