  success: boolean;
  isNewRecord: boolean;
  previousScore: number | null;
  newScore: number;
  rank: number | null;
  message?: string;
}

export interface LeaderboardResponse {
  success: boolean;
  difficulty: string;
  leaderboard: LeaderboardEntry[];
  currentUserRank: {
    rank: number;
    score: number;
  } | null;
  totalEntries: number;
}

/**
 * 사용자 ID 조회 (Supabase Auth 기반)
 * 이전: localStorage UUID → 현재: Supabase 익명 로그인 user.id
 */
export async function getUserId(): Promise<string> {
